actions.script:
if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    ec.user.setPreference(preferenceKey, preferenceValue)
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    ec.user.setPreference(preferenceKey, preferenceValue)
}

const brand = ['primary', 'secondary', 'accent', 'positive', 'negative', 'info', 'warning']
const scheme = colorSchemeId ? ec.entity.find('moqui.screen.ScreenColorScheme').condition('colorSchemeId', colorSchemeId)
        .disableAuthz().useCache(true).one() : null
let css = ''
if (scheme) {
    const colors = ec.entity.find('moqui.screen.ScreenColorSchemeColor').condition('colorSchemeId', colorSchemeId)
            .orderBy('colorName').disableAuthz().useCache(true).list()
    const modes = { SCM_LIGHT: [], SCM_DARK: [] }
    for (let i = 0; i < colors.length; i++) {
        const color = colors.get(i)
        const name = String(color.colorName || ''), value = String(color.colorValue || '').trim()
        const decls = modes[color.colorModeEnumId]
        if (!decls) continue
        if (!/^[a-z][a-z0-9-]{0,40}$/.test(name) || !value || /[;{}<>\\"'!]/.test(value)) {
            ec.logger.error('Color scheme ' + colorSchemeId + ' color ' + name + ' is not a CSS name and value, left out')
            continue
        }
        const dark = color.colorModeEnumId === 'SCM_DARK'
        if (brand.includes(name)) decls.push('--q-' + name + ':' + value + ' !important')
        else if (dark && name === 'link') decls.push('--m-link:var(--m-accent-dark-link, ' + value + ')')
        else decls.push('--m-' + name + ':' + value)
        if (dark && name === 'panel-bg') decls.push('--q-dark:' + value + ' !important')
        if (dark && name === 'page-bg') decls.push('--q-dark-page:' + value + ' !important')
    }
    css = '/* color scheme ' + colorSchemeId + ' */\n'
    if (modes.SCM_LIGHT.length) css += 'body:not(.body--dark) { ' + modes.SCM_LIGHT.join('; ') + '; }\n'
    if (modes.SCM_DARK.length) css += 'body.body--dark { ' + modes.SCM_DARK.join('; ') + '; }\n'
    if (scheme.extraCss) css += scheme.extraCss + '\n'
}
ec.web.sendTextResponse(css, 'text/css')

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const localeText = String(locale || ec.user.locale || 'en_US').replace('-', '_')
    const messages = {}
    for (const key of ['default', localeText.split('_')[0], localeText]) {
        const rows = ec.entity.find('moqui.basic.LocalizedMessage').condition('locale', key).disableAuthz().list()
        for (let i = 0; i < rows.length; i++) { const row = rows.get(i); messages[row.original] = row.localized }
    }
    ec.web.sendJsonResponse({locale: localeText, messages: messages})
}
